for q in "our systems don't talk to each other" "systems not talking to each other" "software systems that don't integrate" "website gets traffic but no" "why is my website getting traffic but no" "website traffic but no enquiries" "spending too much time on manual reports" "how to stop manual reporting" "automate weekly reports" "want to use ai but don't know where to start" "how to start with ai in my business" "where to start with ai" "old software" "our software is outdated" "legacy software replace" "i have an app idea but no technical" "have an idea but no developer" "how to build an app with no technical team" "inventory doesn't match" "inventory count does not match" "inventory discrepancy" "erp implementation failed" "failed erp implementation" "why erp fails" "erp project failed what to do"; do
  echo "## $q"
  curl -s -A "Mozilla/5.0" "https://suggestqueries.google.com/complete/search?client=firefox&hl=en&q=$(python3 -c 'import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))' "$q")" ; echo
done
